(() => {
 'use strict';const RI=window.RI,esc=RI.esc;
 RI.mountNotificationChannels=host=>{
  const alive=()=>host.isConnected;let state,busy=false;
  const supported=()=>window.isSecureContext&&'serviceWorker'in navigator&&'PushManager'in window&&'Notification'in window;
  const request=(suffix,input)=>RI.dashboardRequest('notifications/channels'+suffix,input);
  const message=text=>{if(alive())host.querySelector('[data-channel-message]').textContent=text;};
  function paint(){if(!alive())return;host.innerHTML='<section class="workspace-band"><h2>بیرون از سایت هم باخبر شو</h2><p class="field__hint">کانال‌ها فقط با انتخاب تو فعال می‌شوند. متن اعلان عمومی است؛ جزئیات حساب و تیکت فقط داخل صندوق نمایش داده می‌شود.</p>'+[['email','ایمیل'],['sms','پیامک'],['push','پوش مرورگر']].map(([id,label])=>'<div class="syncrow"><div><b>'+label+'</b><p class="field__hint">'+(state.available[id]?(id==='email'?(state.emailVerified?'ایمیل تأییدشده: '+esc(state.email):'ابتدا ایمیلت را تأیید کن'):id==='sms'?'فقط به شمارهٔ تأییدشدهٔ حساب؛ حداکثر ۵ پیام در روز، بدون خبرهای تبلیغاتی':'با اجازهٔ مرورگر؛ اتصال هر دستگاه جداست'):'سرویس هنوز راه‌اندازی نشده است')+'</p></div>'+RI.switchHtml({checked:state.enabled[id],disabled:!state.available[id]||(id==='email'&&!state.emailVerified)||(id==='sms'&&!RI.state.account.mobileVerified)||(id==='push'&&!state.devices.length),label:'دریافت '+label}).replace('<input','<input data-channel="'+id+'"')+'</div>').join('')+'<div class="workspace-tools"><div class="field"><label class="field__label" for="notice-email">ایمیل دریافت اعلان</label><input class="input" id="notice-email" type="email" dir="ltr" maxlength="254" autocomplete="email" value="'+esc(state.pendingEmail||state.email)+'" '+(!state.available.email?'disabled':'')+'></div><button class="btn btn--soft" type="button" data-email-start '+(!state.available.email?'disabled':'')+'>ارسال کد تأیید</button></div>'+(state.pendingEmail?'<div class="workspace-tools"><div class="field"><label class="field__label" for="notice-email-code">کد شش‌رقمی ایمیل</label><input class="input" id="notice-email-code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" dir="ltr"></div><button class="btn btn--soft" type="button" data-email-verify>تأیید ایمیل</button></div>':'')+'<div class="btnrow"><button class="btn btn--soft" type="button" data-push-connect '+(!state.available.push||!supported()?'disabled':'')+'>'+RI.icon('bell')+'اتصال این مرورگر</button><button class="btn btn--ghost" type="button" data-push-disconnect '+(!supported()?'disabled':'')+'>قطع اتصال این مرورگر</button><button class="btn btn--primary" type="button" data-channel-save>ذخیرهٔ کانال‌ها</button></div>'+(!supported()?'<p class="field__hint">پوش در این مرورگر در دسترس نیست؛ ایمیل و پیامک مستقل‌اند.</p>':'')+'<p role="status" data-channel-message></p><details class="allsteps"><summary>وضعیت ارسال‌های اخیر</summary>'+state.history.map(item=>'<div class="history-row"><b>'+esc({email:'ایمیل',sms:'پیامک',push:'پوش'}[item.channel])+'</b><span>'+esc({pending:'در صف',sending:'در حال ارسال',accepted:'پذیرفته‌شده توسط سرویس',uncertain:'نتیجه نامشخص؛ بدون تکرار خودکار',limited:'سقف روزانه',expired:'اتصال مرورگر منقضی شده',paused:'متوقف‌شده توسط مدیر'}[item.status]||item.status)+'</span><small>'+RI.date(Number(item.created_at))+'</small></div>').join('')+'<p class="field__hint">پذیرش سرویس به معنی رسیدن پیام به گوشی یا صندوق ورودی نیست. برای جلوگیری از ارسال تکراری، نتیجهٔ نامشخص خودکار تکرار نمی‌شود.</p></details></section>';}
  function showPolicy(){host.querySelectorAll('[data-channel]').forEach(input=>{if(state.adminEnabled?.[input.dataset.channel]===false)input.closest('.syncrow').querySelector('.field__hint').textContent='این کانال فعلاً توسط مدیر غیرفعال است؛ انتخاب قبلی تو حفظ شده است.';});const note=document.createElement('p');note.className='field__hint';note.textContent='دریافت بیرون از سایت به فعال‌بودن کانال توسط مدیر، پیکربندی سرویس و انتخاب تو وابسته است.';host.querySelector('.workspace-band h2')?.after(note);}
  async function action(button,fn){if(busy)return;busy=true;button.disabled=true;try{const result=await fn();if(result){state=result;paint();showPolicy();}RI.toast('تنظیم اعلان به‌روزرسانی شد');}catch(e){message(e.message);RI.toast(e.message,{kind:'error'});}finally{busy=false;if(button.isConnected)button.disabled=false;}}
  RI.delegate(host,'click','[data-email-start]',(e,b)=>action(b,()=>request('/email/start',{email:host.querySelector('#notice-email').value.trim()})));
  RI.delegate(host,'click','[data-email-verify]',(e,b)=>action(b,()=>request('/email/verify',{code:RI.searchText(host.querySelector('#notice-email-code').value).trim()})));
  RI.delegate(host,'click','[data-channel-save]',(e,b)=>action(b,()=>request('',Object.fromEntries([...host.querySelectorAll('[data-channel]')].map(x=>[x.dataset.channel,x.checked])))));
  RI.delegate(host,'click','[data-push-connect]',async(e,b)=>{if(busy)return;const permission=await Notification.requestPermission();if(permission!=='granted'){message('مجوز اعلان داده نشد؛ از تنظیمات مرورگر می‌توانی تغییرش بدهی.');return;}action(b,async()=>{await navigator.serviceWorker.register('/notification-sw.js',{scope:'/dashboard/'});const registration=await navigator.serviceWorker.ready;let sub=await registration.pushManager.getSubscription();if(!sub){const raw=atob(state.publicKey.replace(/-/g,'+').replace(/_/g,'/'));sub=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:Uint8Array.from(raw,c=>c.charCodeAt(0))});}return request('/push/subscribe',{subscription:sub.toJSON()});});});
  RI.delegate(host,'click','[data-push-disconnect]',(e,b)=>action(b,async()=>{const registration=await navigator.serviceWorker.getRegistration('/dashboard/'),sub=await registration?.pushManager.getSubscription();if(sub){const result=await request('/push/unsubscribe',{endpoint:sub.endpoint});await sub.unsubscribe();return result;}return request('');}));
  host.innerHTML='<p role="status">در حال دریافت کانال‌های اعلان…</p>';request('').then(value=>{state=value;paint();if(alive())showPolicy();}).catch(e=>{if(alive())host.textContent=e.message;});
 };
})();
